		typeof artifact.tokenCount !== "number" ||
		artifact.tokenCount < MINIMUM_CORPUS_TOKENS
	) {
		return {
			reason: `corpus holds ${String(artifact.tokenCount)} tokens, below the floor of ${MINIMUM_CORPUS_TOKENS}`,
		};
	}

